class Solution {
public:
    vector<int> sortTransformedArray(vector<int>& nums, int a, int b, int c) {
        auto f = [&](int x) { return a * x * x + b * x + c; };
        int n = nums.size();
        vector<int> res(n);
        int l = 0, r = n - 1;
        if (a >= 0) {
            int idx = n - 1;
            while (l <= r) {
                int vl = f(nums[l]), vr = f(nums[r]);
                if (vl >= vr) { res[idx--] = vl; l++; }
                else { res[idx--] = vr; r--; }
            }
        } else {
            int idx = 0;
            while (l <= r) {
                int vl = f(nums[l]), vr = f(nums[r]);
                if (vl <= vr) { res[idx++] = vl; l++; }
                else { res[idx++] = vr; r--; }
            }
        }
        return res;
    }
};

class Solution {
    public int[] sortTransformedArray(int[] nums, int a, int b, int c) {
        int n = nums.length;
        int[] res = new int[n];
        int l = 0, r = n - 1;
        if (a >= 0) {
            int idx = n - 1;
            while (l <= r) {
                int vl = f(nums[l], a, b, c), vr = f(nums[r], a, b, c);
                if (vl >= vr) { res[idx--] = vl; l++; }
                else { res[idx--] = vr; r--; }
            }
        } else {
            int idx = 0;
            while (l <= r) {
                int vl = f(nums[l], a, b, c), vr = f(nums[r], a, b, c);
                if (vl <= vr) { res[idx++] = vl; l++; }
                else { res[idx++] = vr; r--; }
            }
        }
        return res;
    }
    private int f(int x, int a, int b, int c) {
        return a * x * x + b * x + c;
    }
}

